Assistant: Для создания калькулятора с графическим интерфейсом в C# можно использовать Windows Forms. 
Пример:

using System;
using System.Windows.Forms;

namespace Calculator
{
    public partial class Form1 : Form
    {
        double num1, num2, result;
        char operation;

        public Form1()
        {
            InitializeComponent();
        }

        private void btnOne_Click(object sender, EventArgs e)
        {
            txtDisplay.Text = txtDisplay.Text + btnOne.Text;
        }

        private void btnTwo_Click(object sender, EventArgs e)
        {
            txtDisplay.Text = txtDisplay.Text + btnTwo.Text;
        }

        // Аналогичные методы для остальных цифр

        private void btnPlus_Click(object sender, EventArgs e)
        {
            num1 = double.Parse(txtDisplay.Text);
            txtDisplay.Text = "";
            operation = '+';
        }

        private void btnMinus_Click(object sender, EventArgs e)
        {
            num1 = double.Parse(txtDisplay.Text);
            txtDisplay.Text = "";
            operation = '-';
        }

        private void btnMultiply_Click(object sender, EventArgs e)
        {
            num1 = double.Parse(txtDisplay.Text);
            txtDisplay.Text = "";
            operation = '*';
        }

        private void btnDivide_Click(object sender, EventArgs e)
        {
            num1 = double.Parse(txtDisplay.Text);
            txtDisplay.Text = "";
            operation = '/';
        }

        private void btnEqual_Click(object sender, EventArgs e)
        {
            num2 = double.Parse(txtDisplay.Text);
            switch (operation)
            {
                case '+':
                    result = num1 + num2;
                    txtDisplay.Text = result.ToString();
                    break;
